const defaultWizard=()=>({purpose:'Site visit',priority:'planned',origin:'',destination:'',departDate:dateOffset(2),departTime:'08:00',requiredArrivalDate:'',requiredArrival:'',returnDate:'',returnTime:'',people:'1',department:'Site Operations',site:'',flexibility:'30',notes:'',roster:'',preferredMode:'',userId:sessionId||'usr-worker'});
