function remember(){saveDB(db);render();}
function notify(message,type='success'){
 ui.notice={message,type};
 // Preserve inputs in an open Admin modal when validation fails.
 const activeDialog=document.querySelector('.dialog');
 if((activeDialog || document.getElementById('wizard-form')) && type==='error' && app?.insertAdjacentHTML){
   document.querySelector('.toast')?.remove();
   app.insertAdjacentHTML('beforeend',toast());
 }else render();
 clearTimeout(notify.timer);notify.timer=setTimeout(()=>{ui.notice=null;document.querySelector('.toast')?.remove();},4200);
}
function mutate(fn,success){
 try{ const result=fn();saveDB(db);if(success)notify(success);else render();return result;}
 catch(e){ notify(e instanceof Error?e.message:'Something went wrong.','error');return null; }
}
function go(view){ui.view=view;ui.notificationOpen=false;ui.roleMenuOpen=false;ui.modal=null;ui.page=1;ui.navOpen=false;if(view==='new'&&!ui.editingDraft){ui.wizard=defaultWizard();ui.wizard.userId=isAdmin()?'usr-worker':sessionId;ui.wizardStep=0;}window.scrollTo({top:0,behavior:'instant'});render();}
const navBtn=([view,label,name])=>`<button class="side-link ${ui.view===view?'active':''}" data-nav="${view}" aria-current="${ui.view===view?'page':'false'}" aria-label="${esc(label)}">${icon(name,20)}<span>${esc(label)}</span>${view==='admin-requests'&&numAttention()?`<span class="nav-count">${numAttention()}</span>`:''}</button>`;
function brand(small=false){return `<div class="brand ${small?'brand-small':''}"><span class="brand-mark" aria-hidden="true"><i></i><b></b></span><span class="brand-name">ProRack<span>Move</span><small>EMPLOYEE TRAVEL</small></span></div>`;}
function sidebar(){const menu=isAdmin()?adminNav:employeeNav;return `<aside class="sidebar"><div class="sidebar-brand">${brand()}</div><p class="sidebar-label">WORKSPACE</p><nav class="side-nav" aria-label="Main navigation">${menu.map(navBtn).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-help"><span class="soft-icon orange">${icon('sparkle',19)}</span><strong>Thoughtful journeys.</strong><p>Every trip, a little easier.</p><button data-nav="help" class="text-link">How it works ${icon('arrowRight',14)}</button></div><div class="sidebar-footer"><span class="online-dot"></span> Local demo mode <span>v1.1</span></div></div></aside>`;}
function notificationsPanel(){const me=currentUser();const notes=db.notifications.filter(n=>n.userId===me?.id).slice(0,8);return `<div class="notifications-popover" role="dialog" aria-label="Notifications"><div class="popover-head"><strong>Notifications</strong><button class="text-link" data-action="mark-read">Mark all read</button></div>${notes.length?notes.map(n=>`<button class="notification-item ${n.read?'is-read':''}" data-action="open-notification" data-id="${esc(n.id)}"><span class="soft-icon ${n.read?'blue':'orange'}">${icon(n.read?'checkCircle':'bell',17)}</span><span><strong>${esc(n.text)}</strong><small>${timeAgo(n.time)}</small></span></button>`).join(''):emptyState('All caught up','You have no notifications.','bell')}</div>`;}
function timeAgo(t){const diff=Date.now()-new Date(t).getTime();if(diff<60000)return 'Just now';if(diff<3600000)return `${Math.max(1,Math.floor(diff/60000))} min ago`;if(diff<86400000)return `${Math.floor(diff/3600000)} hours ago`;return niceDate(t.slice(0,10));}
function header(){const me=currentUser();const unread=db.notifications.filter(n=>n.userId===sessionId&&!n.read).length;return `<header class="topbar"><div class="top-left"><div class="mobile-brand">${brand(true)}</div><div class="breadcrumb">Workspace ${icon('chevronRight',14)} <b>${esc(viewTitle())}</b></div></div><div class="top-right"><span class="demo-chip"><span class="demo-dot"></span> DEMO MODE</span><button class="tour-launch" data-action="tour-start" title="Start guided stakeholder demo">${icon('sparkle',16)} <span>Guided tour</span></button><button class="icon-button" aria-label="Open notifications" data-action="notifications" aria-expanded="${ui.notificationOpen}">${icon('bell',21)}${unread?`<span class="notification-dot"></span>`:''}</button><span class="top-separator"></span><button class="profile-button" data-action="role-menu" aria-label="Change demo profile" aria-expanded="${ui.roleMenuOpen}">${avatar(me)}<span class="profile-meta"><strong>${esc(me?.name)}</strong><small>${isAdmin()?'Travel Admin':roleName(me?.role)}</small></span>${icon('chevronDown',15)}</button>${ui.roleMenuOpen?roleMenu():''}${ui.notificationOpen?notificationsPanel():''}</div></header>`;}
function roleMenu(){return `<div class="profile-popover"><p class="dropdown-label">SWITCH DEMO PERSONA</p>${db.users.filter(u=>['usr-worker','usr-employee','usr-manager','usr-admin'].includes(u.id)).map(u=>`<button class="switch-persona ${sessionId===u.id?'selected':''}" data-action="switch-persona" data-id="${u.id}">${avatar(u,'small')}<span><strong>${esc(u.name)}</strong><small>${roleName(u.role)}</small></span>${sessionId===u.id?icon('check',17):''}</button>`).join('')}<div class="popover-divider"></div>${!isAdmin()?`<button class="switch-persona" data-nav="profile">${icon('user',18)}<span>My profile</span></button>`:''}<button class="switch-persona logout" data-action="logout">${icon('logout',18)} <span>Back to demo login</span></button></div>`;}
function bottomNav(){const menu=isAdmin()?adminNav.slice(0,4):employeeNav;return `<nav class="bottom-nav" ${ui.modal?'inert':''} aria-label="Mobile navigation">${menu.map(([view,label,name])=>`<button data-nav="${view}" aria-current="${ui.view===view?'page':'false'}" class="bottom-link ${ui.view===view?'active':''}">${icon(name,21)}<span>${view==='new'?'Plan':esc(label)}</span></button>`).join('')}${isAdmin()?`<button class="bottom-link ${ui.navOpen?'active':''}" data-action="workspace-menu" aria-expanded="${ui.navOpen}">${icon('menu',21)}<span>More</span></button>`:''}</nav>${ui.navOpen?`<nav class="mobile-menu" aria-label="More workspace pages"><div class="popover-head"><strong>Your workspace</strong><button class="icon-button" data-action="workspace-menu" aria-label="Close navigation">${icon('x',18)}</button></div>${adminNav.map(navBtn).join('')}</nav>`:''}`;}
let previousModalKey='', previousView='', returnFocus=null;
function restoreControl(source){
 if(!source)return;
 const root=document.querySelector('.dialog')||document;
 const elements=[...root.querySelectorAll('button,input,select,textarea')];
 const target=elements.find(el=>source.name?el.name===source.name:source.dataset?.action?el.dataset.action===source.dataset.action&&el.dataset.id===source.dataset.id:source.dataset?.nav?el.dataset.nav===source.dataset.nav:false);
 target?.focus();
 if(target?.setSelectionRange&&typeof source.selectionStart==='number'&&['text','search',''].includes(target.type))target.setSelectionRange(source.selectionStart,source.selectionEnd);
}
function syncAccessibility(focused){
 if(!document.querySelectorAll)return;
 document.querySelectorAll('.admin-table-wrap').forEach(el=>{el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label','Travel requests table; scroll horizontally for more columns');});
 document.querySelectorAll('.tab').forEach(el=>el.setAttribute('aria-pressed',String(el.classList.contains('active'))));
 document.querySelectorAll('.purpose-tile,.choice,.mode-choice,.persona-card').forEach(el=>el.setAttribute('aria-pressed',String(el.classList.contains('selected'))));
 const modalKey=ui.modal?`${ui.modal.type}:${ui.modal.id||''}`:'';
 if(modalKey&&modalKey!==previousModalKey){if(!previousModalKey)returnFocus=focused;document.querySelector('.dialog')?.focus();}
 else if(!modalKey&&previousModalKey){restoreControl(returnFocus);returnFocus=null;}
 else if(previousView&&previousView!==ui.view&&!modalKey){document.querySelector('.page-content')?.focus({preventScroll:true});}
 else restoreControl(focused);
 previousModalKey=modalKey;previousView=ui.view;
}
function render(){
 if(!app)return;
 const focused=document.activeElement;
 if(!sessionId || !currentUser()){app.innerHTML=loginPage()+(ui.notice?toast(): '');document.body.className='page-login';syncAccessibility(focused);return;}
 const safeView=isAdmin()?['dashboard','admin-requests','planner','allocations','people','reports','settings','new','help'].includes(ui.view):['home','new','requests','trips','help','profile'].includes(ui.view);
 if(!safeView)ui.view=isAdmin()?'dashboard':'home';
 let body='';switch(ui.view){
  case 'home':body=employeeHome();break;case 'new':body=requestWizard();break;case 'requests':body=employeeRequests();break;case 'trips':body=employeeTrips();break;case 'profile':body=profilePage();break;case 'help':body=helpPage();break;
  case 'dashboard':body=adminDashboard();break;case 'admin-requests':body=adminRequests();break;case 'planner':body=plannerPage();break;case 'allocations':body=allocationsPage();break;case 'people':body=peoplePage();break;case 'reports':body=reportsPage();break;case 'settings':body=settingsPage();break;
  default:body=employeeHome();
 }
 app.innerHTML=`<a class="skip-link" href="#workspace-main">Skip to main content</a><div class="app-shell" ${ui.modal?'inert':''}>${sidebar()}<div class="app-main">${header()}<main id="workspace-main" tabindex="-1" class="page-content page-${esc(ui.view)}">${body}</main><footer class="main-footer"><span>© ProRack · Internal concept demo</span><span>Designed for simpler journeys. Built for your team.</span></footer></div></div>${bottomNav()}${ui.tourOpen?tourCard():''}${ui.modal?modalShell():''}${ui.notice?toast():''}`;
 document.body.className='page-app';syncAccessibility(focused);
}
function tourCard(){const s=tourSteps[ui.tourIndex];return `<aside class="tour-card" ${ui.modal?'inert':''} role="region" aria-label="Guided MVP demonstration"><div class="tour-top"><span>${icon('sparkle',16)} STAKEHOLDER WALKTHROUGH</span><button data-action="tour-close" aria-label="Close guided tour">${icon('x',18)}</button></div><div class="tour-steps">${tourSteps.map((_,i)=>`<button aria-label="Tour step ${i+1}" class="tour-dot ${i===ui.tourIndex?'active':i<ui.tourIndex?'complete':''}" data-action="tour-step" data-id="${i}"></button>`).join('')}</div><span class="tour-counter">STEP ${ui.tourIndex+1} OF ${tourSteps.length}</span><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p><div class="tour-footer"><button class="btn btn-outline" data-action="tour-prev" ${ui.tourIndex===0?'disabled':''}>${icon('arrowLeft',16)} Back</button><button class="btn btn-primary" data-action="${ui.tourIndex===tourSteps.length-1?'tour-close':'tour-next'}">${ui.tourIndex===tourSteps.length-1?'Finish tour':'Next stop'} ${icon('arrowRight',16)}</button></div></aside>`;}
function tourJump(index){ui.tourIndex=Math.max(0,Math.min(tourSteps.length-1,Number(index)||0));ui.tourOpen=true;const step=tourSteps[ui.tourIndex];if(sessionId!==step.role){roleSelect(step.role);}ui.view=step.view;ui.modal=null;ui.roleMenuOpen=false;ui.notificationOpen=false;if(step.view==='new'){ui.editingDraft=null;ui.wizard=defaultWizard();ui.wizard.userId=step.role;ui.wizardStep=step.wizardStep||0;}render();}
function toast(){return `<div role="${ui.notice?.type==='error'?'alert':'status'}" aria-atomic="true" class="toast ${ui.notice?.type==='error'?'toast-error':''}">${ui.notice?.type==='error'?icon('alert',22):illustration('success')} <span>${esc(ui.notice?.message||'')}</span><button data-action="dismiss-toast" aria-label="Dismiss">${icon('x',17)}</button></div>`;}
const roleName=role=>({worker:'Site worker',employee:'Employee / engineer',manager:'Manager',senior_manager:'Senior manager',admin:'Travel Admin'}[role]||role||'Employee');
function loginPage(){return `<div class="login-shell"><div class="login-left"><div class="login-brand">${brand()}</div><div class="login-main"><span class="login-eyebrow"><span class="online-dot"></span> YOUR TEAM, IN MOTION</span><h1>Where every<br>journey <em>begins.</em></h1><p>Travel planned. Teams moving. A better way to coordinate every trip across ProRack.</p><div class="login-highlights"><span>${icon('checkCircle',17)} Simple travel requests</span><span>${icon('checkCircle',17)} Smarter group transport</span><span>${icon('checkCircle',17)} One clear journey</span></div></div><div class="login-illustration">${heroTravelArt('login-art')}</div><div class="login-foot">ProRack Move · Employee travel management <span>LOCAL MVP PREVIEW</span></div></div><div class="login-right"><div class="login-card"><span class="tiny-kicker">EXPLORE THE EXPERIENCE</span><h2>Welcome to Move <span class="wave">✦</span></h2><p>Select a demo persona to see how travel planning works for every team member.</p><button class="btn btn-outline tour-login-button" data-action="tour-start">${icon('sparkle',17)} Show me the 7-step guided demo</button><div class="login-personas">${[
  ['usr-worker','Site worker','Request your pickup','hand'],['usr-employee','Employee','Plan site travel','briefcase'],['usr-manager','Manager','Arrange a client visit','user'],['usr-admin','Travel Admin','Coordinate all journeys','layers']
 ].map(([id,label,subtitle,ic])=>`<button class="persona-card ${ui.selectedPersona===id?'selected':''}" data-action="select-persona" data-id="${id}"><span class="persona-symbol ${id==='usr-admin'?'mint':id==='usr-manager'?'peach':'blue'}">${icon(ic,24)}</span><span class="persona-card-text"><strong>${label}</strong><small>${subtitle}</small></span><span class="persona-check">${ui.selectedPersona===id?icon('check',15):''}</span></button>`).join('')}</div><button class="btn btn-primary btn-large btn-full" data-action="enter-demo">Enter demo workspace ${icon('arrowRight',19)}</button><div class="login-note">${icon('shield',16)} This is an interactive local demo. No real authentication, bookings or external services are connected.</div></div><p class="login-bottom">Built with care for the people who keep ProRack moving.</p></div></div>`;}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening';}
const illustrationMini=()=>`<div class="hero-mini-art">${heroTravelArt('mini-art')}</div>`;
function employeeHome(){
 const me=currentUser(), mine=myRequests(),current=mine.find(r=>r.status==='allocated')||mine.find(r=>r.status==='approved');
 const assigned=current?db.plans.find(p=>p.id===current.planId):null;
 const outstanding=mine.filter(r=>['submitted','under_review','approved','needs_info'].includes(r.status)).length;
 return `<div class="welcome-line"><div><p class="eyebrow">${greeting().toUpperCase()}</p><h1>Hi, ${esc(me.first)} <span class="hello-emoji">✳</span></h1><p class="lead">Let's make your next journey effortless.</p></div><span class="date-bubble">${icon('calendar',16)} ${niceDate(dateOffset(0),{weekday:'short',day:'numeric',month:'short'})}</span></div>
 <section class="employee-hero"><div class="hero-copy"><span class="hero-kicker">✦ PLAN TOGETHER. TRAVEL SMARTER.</span><h2>Your next journey,<br><em>beautifully planned.</em></h2><p>Tell us where you need to go. We'll help coordinate the rest.</p>${button('Plan a new journey','new-request',{class:'btn-hero',icon:'plus',arrow:true})}</div>${illustrationMini()}</section>
 <div class="metric-strip"><div class="mini-stat"><span class="mini-stat-icon blue">${icon('clipboard',20)}</span><span><strong>${mine.length}</strong><small>My requests</small></span></div><div class="mini-stat"><span class="mini-stat-icon orange">${icon('clock',20)}</span><span><strong>${outstanding}</strong><small>Awaiting action</small></span></div><div class="mini-stat"><span class="mini-stat-icon mint">${icon('checkCircle',20)}</span><span><strong>${mine.filter(r=>['allocated','completed'].includes(r.status)).length}</strong><small>Travel arranged</small></span></div></div>
 <div class="employee-columns"><div class="stack">${sectionCard('Your upcoming journey',current?upcomingCard(current,assigned):emptyState('Nothing on the calendar','When Admin allocates a trip, your itinerary will appear here.','calendar',button('Plan travel','new-request',{variant:'btn-soft'})),current?button('View all trips','view-trips',{variant:'btn-text',arrow:true}):'', 'calendar')}${sectionCard('Recent requests',mine.length?`<div class="compact-list">${mine.slice(0,3).map(r=>requestCompact(r)).join('')}</div>`:emptyState('Your travel history starts here','Create your first travel request to get started.','clipboard'),button('See all requests','view-requests',{variant:'btn-text',arrow:true}),'clipboard')}</div><div class="stack"><div class="how-card"><span class="tiny-kicker">MADE SIMPLE</span><h2>Travel in just<br>three little steps.</h2>${[['1','Tell us your plan','Where, when, and why you need to travel.'],['2','We plan together','Admin reviews and finds the right transport.'],['3','You’re on your way','See your confirmed travel details in one place.']].map(([n,t,d])=>`<div class="how-step"><b>${n}</b><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}<div class="how-decoration">${illustration('team')}</div></div><div class="tip-card"><span class="tip-star">${icon('sparkle',20)}</span><strong>A little planning goes a long way.</strong><p>Submitting in advance helps Admin organize shared pickups and avoid last-minute changes.</p></div></div></div>`;
}
function requestCompact(r){return `<button class="compact-row" data-action="open-request" data-id="${esc(r.id)}"><span class="route-icon">${icon(r.priority==='emergency'?'alert':'mapPin',19)}</span><span class="compact-main"><strong>${esc(r.destination)}</strong><small>${shortDate(r.departDate)} · ${esc(r.purpose)} · ${r.people} ${Number(r.people)===1?'person':'people'}</small></span>${badge(r.status)}${icon('chevronRight',17)}</button>`;}
function upcomingCard(r,plan){return `<div class="upcoming-travel"><div class="upcoming-top"><span class="upcoming-label">${icon('calendar',15)} ${shortDate(r.departDate)} · ${esc(formatTime(r.departTime))}</span>${badge(r.status)}</div><div class="trip-path"><div><span class="trip-dot"></span><small>FROM</small><strong>${esc(r.origin)}</strong></div><span class="trip-path-line">${icon('arrowRight',22)}</span><div><span class="trip-dot end"></span><small>TO</small><strong>${esc(r.destination)}</strong></div></div>${r.requiredArrivalDate||r.requiredArrival?`<p class="arrival-note">Required arrival: ${esc(arrivalSummary(r))}</p>`:''}<div class="upcoming-footer"><span>${icon('users',17)} ${r.people} traveler${Number(r.people)!==1?'s':''}</span><span>${icon(plan?.mode==='flight'?'plane':plan?.mode==='train'?'train':'bus',17)} ${esc(modeName(plan?.mode)||'Pending assignment')}</span><button data-action="open-request" data-id="${esc(r.id)}">Details ${icon('arrowRight',16)}</button></div></div>`;}
const modeName=m=>MODES.find(x=>x.id===m)?.label||'';
function employeeRequests(){const mine=myRequests();const tabs=[['all','All requests'],['submitted','Pending'],['allocated','Allocated'],['completed','Completed']];const filtered=mine.filter(r=>(ui.requestTab==='all'||(ui.requestTab==='submitted'?['submitted','under_review','approved','needs_info'].includes(r.status):r.status===ui.requestTab))&&[r.id,r.origin,r.destination,r.purpose].join(' ').toLowerCase().includes(ui.requestQuery.trim().toLowerCase()));return `${topSection('YOUR JOURNEYS','My travel requests','A simple view of every journey you’ve requested.',button('Plan new travel','new-request',{icon:'plus'}))}<div class="surface-card page-card"><div class="request-search"><form id="employee-search-form" class="search-form">${icon('search',18)}<input name="query" type="search" aria-label="Search my requests" placeholder="Search a destination or request ID" value="${esc(ui.requestQuery)}"/><button type="submit" aria-label="Search my requests">${icon('arrowRight',18)}</button></form><span>${filtered.length} matching request${filtered.length===1?'':'s'}</span></div><div class="tab-row">${tabs.map(([k,t])=>`<button class="tab ${ui.requestTab===k?'active':''}" data-action="request-tab" data-id="${k}">${t}</button>`).join('')}</div>${filtered.length?`<div class="request-cards">${filtered.map(r=>`<button class="request-card" data-action="open-request" data-id="${esc(r.id)}"><span class="request-id">${esc(r.id)}${r.priority==='emergency'?priorityBadge(r.priority):''}</span><span class="request-card-heading"><strong>${esc(r.destination)}</strong>${icon('arrowUpRight',19)}</span><span class="request-card-meta">${icon('mapPin',15)} ${esc(r.origin)} ${icon('arrowRight',13)} ${esc(r.destination)}</span><span class="request-card-bottom">${icon('calendar',15)} ${shortDate(r.departDate)} <span class="dot-sep">·</span> ${r.people} traveler${Number(r.people)!==1?'s':''} ${badge(r.status)}</span></button>`).join('')}</div>`:emptyState('No matching requests','Choose another tab or plan a new journey.','clipboard',button('Plan travel','new-request',{variant:'btn-soft'}))}</div>`;}
function employeeTrips(){const plans=myPlans();return `${topSection('YOUR ITINERARY','Upcoming & past trips','Your confirmed allocations and booking notes, all in one place.',button('Request travel','new-request',{icon:'plus'}))}<div class="trip-grid">${plans.length?plans.map(p=>{const rs=p.requestIds.map(id=>db.requests.find(r=>r.id===id)).filter(r=>r?.userId===sessionId);return `<div class="trip-full-card"><div class="trip-full-top"><span class="mode-icon">${transportArt(p.mode)}</span><div><small>TRANSPORT PLAN ${esc(p.id)}</small><h3>${esc(modeName(p.mode))}</h3></div>${badge(p.status)}</div><div class="trip-full-route">${routeText(rs[0]||{origin:p.pickup,destination:p.drop})}</div><div class="trip-info-grid">${profileLine('Departure',formatDateTime(p.departure))}${rs.map(r=>profileLine('Required arrival ? '+r.id,arrivalSummary(r))).join('')}${profileLine('Pickup point',p.pickup)}${profileLine('Provider',p.provider)}${profileLine('Booking reference',p.bookingRef||'Not yet recorded')}</div><div class="trip-full-foot">${icon('info',17)} ${esc(p.notes||'Please confirm final instructions with Travel Admin.')}</div><div class="trip-pass-actions"><button class="btn btn-outline" data-action="view-pass" data-id="${esc(p.id)}">${icon('clipboard',16)} Preview itinerary</button></div></div>`;}).join(''):emptyState('No trips allocated yet','Once Admin arranges transport, your confirmed plan will appear here.','bus',button('View requests','view-requests',{variant:'btn-soft'}))}</div>`;}
function profilePage(){const me=currentUser();return `${topSection('YOUR ACCOUNT','Profile','Preview account details for the currently selected demo persona.')}<div class="surface-card profile-page">${avatar(me,'large')}<div><h2>${esc(me.name)}</h2><p>${esc(roleName(me.role))} · ${esc(me.department)}</p></div><div class="profile-stats">${profileLine('Primary location',me.location)}${profileLine('Account type',me.login)}${profileLine('Role',roleName(me.role))}</div>${button('Switch demo role','role-menu',{variant:'btn-soft'})}</div>`;}
function field(label,name,opts={}){
 const type=opts.type||'text',value=ui.wizard[name]??opts.value??'';
 if(type==='time')return timeField(label,name,value,opts);
 return `<label class="form-field ${opts.span?'field-span':''}"><span class="field-label">${esc(label)} ${opts.required?'<i>*</i>':name==='requiredArrivalDate'?'<span class="field-optional">(optional)</span>':''}</span>${opts.icon?`<span class="input-wrap">${icon(opts.icon,17)}<input type="${type}" name="${name}" ${['origin','destination'].includes(name)?'list="travel-locations"':''} value="${esc(value)}" ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.min?`min="${esc(opts.min)}"`:''} ${opts.max?`max="${esc(opts.max)}"`:''} ${opts.required?'required':''}></span>`:`<input type="${type}" name="${name}" ${['origin','destination'].includes(name)?'list="travel-locations"':''} value="${esc(value)}" ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.min?`min="${esc(opts.min)}"`:''} ${opts.max?`max="${esc(opts.max)}"`:''} ${opts.required?'required':''}>`}${opts.hint?`<small class="field-hint">${esc(opts.hint)}</small>`:''}</label>`;
}
function requestWizard(){
 const w=ui.wizard,step=ui.wizardStep,me=currentUser();const selectedUser=userById(w.userId||sessionId);
 let content='';
 if(step===0)content=`<div class="wizard-section-head"><span class="step-kicker">STEP 01 / THE WHY</span><h2>What's the purpose?</h2><p>A few details help us arrange the right journey.</p></div><div class="purpose-grid">${PURPOSES.map(p=>`<button type="button" class="purpose-tile ${w.purpose===p?'selected':''}" data-action="choose-purpose" data-id="${esc(p)}"><span class="purpose-icon">${illustration(({'Site visit':'location-pin','Client visit':'car','Project work':'team','Training':'planning','Meeting':'approval','Other':'flight'})[p])}</span><strong>${esc(p)}</strong>${w.purpose===p?`<span class="tile-check">${icon('check',12)}</span>`:''}</button>`).join('')}</div><div class="form-divider"></div><div class="wizard-section-head smaller"><h3>When is it needed?</h3></div><div class="priority-choices"><button type="button" class="choice ${w.priority==='planned'?'selected':''}" data-action="priority" data-id="planned"><span class="choice-icon blue">${icon('calendar',21)}</span><span><strong>Planned travel</strong><small>Arrange travel ahead of time</small></span>${w.priority==='planned'?icon('checkCircle',20):''}</button><button type="button" class="choice ${w.priority==='emergency'?'selected':''}" data-action="priority" data-id="emergency"><span class="choice-icon orange">${icon('alert',21)}</span><span><strong>Emergency travel</strong><small>Need immediate attention</small></span>${w.priority==='emergency'?icon('checkCircle',20):''}</button></div>${isAdmin()?`<div class="form-divider"></div><label class="form-field"><span class="field-label">Requesting on behalf of</span><select name="userId">${db.users.filter(u=>u.role!=='admin').map(u=>`<option value="${esc(u.id)}" ${w.userId===u.id?'selected':''}>${esc(u.name)} · ${roleName(u.role)}</option>`).join('')}</select></label>`:''}`;
 if(step===1)content=`<div class="wizard-section-head"><span class="step-kicker">STEP 02 / THE WHERE & WHEN</span><h2>Where are we taking you?</h2><p>Share your route and the date you need to leave.</p></div><div class="form-grid">${field('Traveling from','origin',{icon:'mapPin',placeholder:'e.g. Kothur, Hyderabad',required:true})}${field('Traveling to','destination',{icon:'mapPin',placeholder:'e.g. Bhiwandi Project Site',required:true})}${field('Departure date','departDate',{type:'date',required:true,min:dateOffset(0)})}${field('Departure time','departTime',{type:'time',required:true})}${field('Required arrival date','requiredArrivalDate',{type:'date',min:w.departDate||dateOffset(0),hint:'Optional: the date you need to arrive'})}${field('Required arrival time','requiredArrival',{type:'time',hint:'Optional: uses departure date if arrival date is blank'})}<label class="form-field"><span class="field-label">Pickup flexibility</span><select name="flexibility">${[['0','Exact departure time'],['15','± 15 minutes'],['30','± 30 minutes'],['60','± 1 hour']].map(([v,l])=>`<option value="${v}" ${w.flexibility===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="form-divider"></div><h3 class="subsection-title">Returning? <span>Optional</span></h3><div class="form-grid">${field('Return date','returnDate',{type:'date',min:w.departDate||dateOffset(0)})}${field('Return time','returnTime',{type:'time'})}</div>`;
 if(step===2)content=`<div class="wizard-section-head"><span class="step-kicker">STEP 03 / THE DETAILS</span><h2>A few final details.</h2><p>Help the Admin team prepare a smooth trip.</p></div><div class="form-grid">${field('Number of travelers','people',{type:'number',min:'1',max:'500',required:true,hint:'For group moves, Admin verifies the traveler roster.'})}${field('Department / team','department',{placeholder:'e.g. Installation'})}${field('Project or site name','site',{placeholder:'e.g. Bhiwandi Site',span:true})}</div><label class="form-field field-span" style="margin-top:19px"><span class="field-label">Traveler names / roster <span class="field-optional">(for group requests)</span></span><textarea name="roster" rows="3" placeholder="Enter names or note where a verified roster will be supplied.">${esc(w.roster)}</textarea></label><label class="form-field field-span" style="margin-top:19px"><span class="field-label">Additional notes ${w.priority==='emergency'?'<i>* Required for emergencies</i>':''}</span><textarea name="notes" rows="4" placeholder="Pickup instructions, accessibility needs, safety requirements or emergency reason...">${esc(w.notes)}</textarea></label>${canRequestMode(selectedUser.role)?`<div class="form-divider"></div><div class="manager-preference"><div class="manager-preference-header"><span class="soft-icon orange">${icon('sparkle',19)}</span><div><strong>Preferred transport mode</strong><small>Available only for managers. Admin makes the final selection.</small></div></div><div class="mode-choices">${[...MODES.map(m=>({id:m.id,label:m.label}))].map(m=>`<button type="button" class="mode-choice ${w.preferredMode===m.id?'selected':''}" data-action="choose-mode" data-id="${m.id}">${transportArt(m.id)}<span>${esc(m.label)}</span></button>`).join('')}</div></div>`:''}<div class="assist-note">${icon('shield',19)} <span>Every employee can include accessibility or safety requirements in the notes. Travel preferences are restricted to management roles.</span></div>`;
 if(step===3)content=`<div class="wizard-section-head"><span class="step-kicker">STEP 04 / READY TO GO</span><h2>Review your journey.</h2><p>Make sure everything looks right before submitting.</p></div><div class="review-ready">${illustration('approval')}<span><strong>One last look.</strong><small>Your Admin team takes it from here.</small></span></div><div class="review-summary"><div class="review-route"><span class="route-icon large">${icon('route',23)}</span><span><small>YOUR JOURNEY</small><strong>${esc(w.origin||'Origin')} ${icon('arrowRight',18)} ${esc(w.destination||'Destination')}</strong></span></div><div class="review-grid">${profileLine('Travel purpose',w.purpose)}${profileLine('Travel type',w.priority==='emergency'?'Emergency':'Planned')}${profileLine('Departure',`${niceDate(w.departDate)} · ${formatTime(w.departTime)}`)}${profileLine('Travelers',`${w.people} person${Number(w.people)===1?'':'s'}`)}${profileLine('Department',w.department)}${profileLine('Required arrival',arrivalSummary(w))}${profileLine('Return',w.returnDate||w.returnTime?formatSchedule(w.returnDate,w.returnTime):'One-way / unspecified')}${canRequestMode(selectedUser.role)?profileLine('Preferred mode',modeName(w.preferredMode)||'No preference'):''}</div>${w.notes?`<div class="review-notes"><strong>Notes</strong><p>${esc(w.notes)}</p></div>`:''}</div><div class="review-disclaimer">${icon('info',20)} <span>Submitting sends your request to the Travel Admin. It does not book travel or guarantee a mode of transportation. You'll see updates here.</span></div>`;
 return `${topSection('PLAN YOUR JOURNEY',ui.editingDraft?'Resume travel draft':'New travel request','Four simple steps and your travel requirement is on its way.')}<div class="wizard-layout"><div class="wizard-card"><div class="wizard-progress" aria-label="Travel request progress">${['Purpose','Your route','Details','Review'].map((s,i)=>`<div aria-current="${i===step?'step':'false'}" class="progress-item ${i<=step?'done':''} ${i===step?'current':''}"><span>${i<step?icon('check',15):i+1}</span><small>${s}</small></div>`).join('')}</div><form id="wizard-form" novalidate>${content}<datalist id="travel-locations">${[...new Set(db.requests.flatMap(r=>[r.origin,r.destination]))].map(place=>`<option value="${esc(place)}"></option>`).join('')}</datalist></form><div class="wizard-actions"><div>${step?button('Back','prev-step',{variant:'btn-outline',icon:'arrowLeft'}):button('Save draft','save-draft',{variant:'btn-outline',icon:'file'})}</div><div>${step<3?button('Continue','next-step',{arrow:true}):button('Submit request','submit-request',{icon:'check',arrow:true})}</div></div></div><aside class="wizard-aside"><div class="aside-illustration">${heroTravelArt('aside-art')}</div><span class="tiny-kicker">GOOD TO KNOW</span><h3>We coordinate.<br>You keep moving.</h3><p>Once submitted, Admin will review your requirement and arrange the most suitable transport.</p><div class="aside-divider"></div><div class="aside-point">${icon('clock',18)} Earlier requests mean better planning</div><div class="aside-point">${icon('users',18)} Group travel is coordinated together</div><div class="aside-point">${icon('bell',18)} You'll see progress updates in-app</div><span class="aside-foot">${icon('shield',15)} Your details stay in this browser demo.</span></aside></div>`;
}
function adminDashboard(){
 const attention=db.requests.filter(r=>['submitted','under_review','needs_info'].includes(r.status)).sort((a,b)=>Number(b.priority==='emergency')-Number(a.priority==='emergency'));
 const all=db.requests.length,allocated=db.requests.filter(r=>r.status==='allocated').length;
 const suggestions=getSuggestions(db.requests);
 return `${topSection('ADMIN WORKSPACE','Everything in motion.','A clearer view of every request, journey and transport plan.',button('New travel request','new-request',{icon:'plus'}))}
 <section class="admin-hero"><div><span class="hero-tag">✦ YOUR OPERATIONS, SIMPLIFIED</span><h2>Better plans.<br>Smarter journeys.</h2><p>Keep everyone moving with one calm, connected workspace.</p><button class="btn btn-hero-light" data-nav="planner">Explore route planning ${icon('arrowRight',18)}</button></div><div class="admin-hero-graphic">${routeSketch()}<div class="floating-tag">${icon('checkCircle',16)} Coordinated travel</div></div></section>
 <div class="admin-stats">${metricCard('Total requests',all,'clipboard','blue','All travel demand')}${metricCard('Needs attention',attention.length,'clock','orange','Waiting for Admin')}${metricCard('Travel allocated',allocated,'checkCircle','mint','Transport assigned')}${metricCard('Travelers planned',db.requests.filter(r=>!['cancelled','rejected','draft'].includes(r.status)).reduce((n,r)=>n+Number(r.people),0),'users','purple','Across all requests')}</div>
 <div class="admin-grid"><div class="stack">${sectionCard('Needs your attention',attention.length?`<div class="admin-table-wrap">${requestTable(attention.slice(0,5),false)}</div>`:emptyState('Inbox is clear','New travel requests will show here.','checkCircle'),button('View request queue','view-admin-requests',{variant:'btn-text',arrow:true}),'clipboard')}${sectionCard('Travel activity',`<div class="activity-list">${db.activity.slice(0,4).map(eventRow).join('')}</div>`,button('View reports','view-reports',{variant:'btn-text',arrow:true}),'clock')}</div><div class="stack">${sectionCard('Smart route suggestions',suggestions.length?`<div class="group-peeks">${suggestions.slice(0,3).map(suggestionPeek).join('')}</div>`:emptyState('No matching routes','New compatible requests will appear here.','route'),button('Open route planner','view-planner',{variant:'btn-text',arrow:true}),'sparkle')}${sectionCard('Quick overview',quickInsights(),'','chart')}</div></div>`;
}
function metricCard(label,value,ic,tone,sub){return `<div class="metric-card"><div class="metric-top"><span class="metric-name">${esc(label)}</span><span class="metric-icon ${tone}">${icon(ic,22)}</span></div><strong>${value}</strong><small>${esc(sub)}</small></div>`;}
function eventRow(a){const user=userById(a.actorId);return `<div class="activity-item"><span class="activity-dot ${a.kind==='allocation'?'green':a.kind==='submitted'?'orange':'blue'}"></span><span><strong>${esc(a.message)}</strong><small>${esc(user.name)} · ${timeAgo(a.time)}</small></span></div>`;}
function suggestionPeek(s){return `<button class="group-peek" data-action="choose-group" data-id="${esc(s.id)}"><span class="group-icon">${icon(s.mode==='train'?'train':'bus',20)}</span><span><strong>${esc(s.destination)}</strong><small>${shortDate(s.date)} · ${s.people} traveler${s.people===1?'':'s'} · ${s.requests.length} request${s.requests.length===1?'':'s'}</small></span>${icon('chevronRight',18)}</button>`;}
function quickInsights(){const count=db.requests.filter(r=>r.priority==='emergency').length,grouped=getSuggestions(db.requests).reduce((n,g)=>n+g.people,0);return `<div class="insight-grid"><div><span class="insight-symbol orange">${icon('alert',20)}</span><strong>${count}</strong><small>Emergency requests</small></div><div><span class="insight-symbol blue">${icon('route',20)}</span><strong>${grouped}</strong><small>Groupable travelers*</small></div></div><p class="micro-disclaimer">*Suggestions use a simple regional/time heuristic. Road routing must be verified manually.</p>`;}
function requestTable(reqs,full=true){if(!reqs.length)return emptyState('No travel requests found','Try a different filter or check back later.','clipboard');return `<table class="data-table"><thead><tr><th>Request / traveler</th><th>Journey</th><th>Departure</th><th>People</th><th>Status</th><th></th></tr></thead><tbody>${reqs.map(r=>`<tr><td><div class="table-user">${avatar(userById(r.userId),'small')}<div><strong>${esc(userById(r.userId).name)}</strong><small>${esc(r.id)} ${r.priority==='emergency'?'<span class="urgent-mini">URGENT</span>':''}</small></div></div></td><td><div class="table-route"><strong>${esc(r.destination)}</strong><small>From ${esc(r.origin)}</small></div></td><td><div class="cell-two"><strong>${shortDate(r.departDate)}</strong><small>${esc(formatTime(r.departTime))}</small></div></td><td><strong>${r.people}</strong></td><td>${badge(r.status)}</td><td><button class="round-arrow" aria-label="View request" data-action="open-request" data-id="${esc(r.id)}">${icon('arrowUpRight',18)}</button></td></tr>`).join('')}</tbody></table>${full?`<div class="table-bottom">Showing ${reqs.length} request${reqs.length!==1?'s':''}</div>`:''}`;}
function adminRequests(){const tabs=[['all','All requests'],['attention','Needs action'],['emergency','Emergency'],['approved','Approved'],['allocated','Allocated'],['completed','Completed']];let requests=[...db.requests].sort((a,b)=>Number(b.priority==='emergency')-Number(a.priority==='emergency')||b.createdAt.localeCompare(a.createdAt));if(ui.adminFilter==='attention')requests=requests.filter(r=>['submitted','under_review','needs_info'].includes(r.status));else if(ui.adminFilter==='emergency')requests=requests.filter(r=>r.priority==='emergency'&&unresolved(r));else if(ui.adminFilter!=='all')requests=requests.filter(r=>r.status===ui.adminFilter);if(ui.query.trim())requests=requests.filter(r=>[r.id,r.origin,r.destination,r.purpose,userById(r.userId).name].join(' ').toLowerCase().includes(ui.query.toLowerCase()));return `${topSection('TRAVEL CONTROL CENTER','Travel requests','Review, prioritize and respond to requirements from every team.',button('Create on behalf','new-request',{icon:'plus'}))}<div class="surface-card admin-list-card"><div class="list-tools"><div class="tabs-scroll">${tabs.map(([k,label])=>`<button class="tab ${ui.adminFilter===k?'active':''}" data-action="admin-filter" data-id="${k}">${label}</button>`).join('')}</div><form id="search-form" class="search-form"><span>${icon('search',18)}</span><input aria-label="Search requests" name="query" placeholder="Search travelers or destinations" value="${esc(ui.query)}"/><button aria-label="Search" type="submit">${icon('arrowRight',16)}</button></form></div><div class="admin-table-wrap">${requestTable(requests)}</div></div><div class="info-line">${icon('info',17)} Mode preferences belong to manager-level users. All final travel allocations are made by Admin.</div>`;}
function plannerPage(){const suggestions=getSuggestions(db.requests);const selected=suggestions.find(s=>s.id===ui.selectedGroup)||suggestions[0];const chosen=selected?.requests.filter(r=>ui.selectedIds?ui.selectedIds.includes(r.id):true)||[];return `${topSection('SMART TRAVEL PLANNING','Route planning','Identify potential shared journeys and prepare transport allocations.',button('See all requests','view-admin-requests',{variant:'btn-outline',icon:'clipboard'}))}<div class="planner-message">${icon('sparkle',19)} <span><strong>Smart suggestions, human decisions.</strong> These groups use matching destinations, travel dates and broad-area heuristics. They are not verified road routes, live services or AI bookings.</span></div><div class="planner-layout"><div class="surface-card planner-list"><div class="panel-title-row"><h2>Suggested opportunities</h2><span class="count-pill">${suggestions.length}</span></div>${suggestions.length?suggestions.map(s=>`<button class="planner-group ${selected?.id===s.id?'selected':''}" data-action="choose-group" data-id="${esc(s.id)}"><span class="group-topline"><span class="sug-tag">${icon('sparkle',14)} Potential grouping</span><span class="confidence-pill">Review route</span></span><strong>${esc(s.destination)}</strong><small>${icon('calendar',14)} ${shortDate(s.date)} <b>·</b> ${s.people} travelers <b>·</b> ${s.requests.length} requests</small><span class="group-footer"><span class="small-avatars">${s.requests.slice(0,3).map(r=>avatar(userById(r.userId),'tiny')).join('')}</span><span>${icon(modeIcon(s.mode),16)} Suggested: ${modeName(s.mode)}</span>${icon('chevronRight',18)}</span></button>`).join(''):emptyState('No new grouping opportunities','Try creating two requests with the same destination and compatible travel times.','route')}</div><div class="surface-card planner-detail">${selected?`<div class="panel-title-row"><div><p class="tiny-kicker">SUGGESTED TRAVEL GROUP</p><h2>${esc(selected.destination)}</h2></div><span class="soft-icon blue">${icon('route',23)}</span></div><div class="planner-summary"><div><strong>${selected.people}</strong><small>Total people</small></div><div><strong>${selected.requests.length}</strong><small>Requests</small></div><div><strong>${shortDate(selected.date)}</strong><small>Travel date</small></div></div><div class="route-map-card">${routeSketch()}<span>Illustrative route only — not mapped to real roads</span></div><div class="pickup-sequence"><div class="sequence-heading"><strong>Pickup sequence to verify</strong><small>Ordered by requested departure &middot; road feasibility unverified</small></div><ol>${chosen.slice().sort((a,b)=>a.departTime.localeCompare(b.departTime)).map((r,i)=>`<li><b>${i+1}</b><span><strong>${esc(r.origin)}</strong><small>${esc(formatTime(r.departTime))} requested &middot; ${r.people} traveler${Number(r.people)===1?'':'s'}</small></span></li>`).join('')}<li class="sequence-destination"><b>${icon('mapPin',15)}</b><span><strong>${esc(selected.destination)}</strong><small>Shared destination</small></span></li></ol></div><div class="suggestion-explanation"><span>${icon('sparkle',19)}</span><div><strong>Why the app surfaced this</strong><p>${esc(selected.reason)}</p></div></div><div class="panel-title-row rows-head"><h3>Include in this plan</h3><small>${chosen.length} selected &middot; ${totalPeople(chosen)} travelers</small></div><div class="selected-travelers">${selected.requests.map(r=>`<label class="traveler-pick"><input type="checkbox" data-action="toggle-member" data-id="${esc(r.id)}" ${(ui.selectedIds??selected.requestIds).includes(r.id)?'checked':''}/>${avatar(userById(r.userId),'small')}<span><strong>${esc(userById(r.userId).name)}</strong><small>${esc(r.origin)} · ${r.people} traveler${r.people!==1?'s':''}</small></span>${badge(r.status)}</label>`).join('')}</div><div class="planning-bottom"><div class="allocation-summary"><span>Suggested transport</span><strong>${icon(modeIcon(selected.mode),19)} ${esc(modeName(selected.mode))}</strong></div><button class="btn btn-primary" data-action="start-group-plan" ${!chosen.length?'disabled':''}>Review & plan transport ${icon('arrowRight',18)}</button></div>`:emptyState('Select a route opportunity','Choose a proposed group from the list to review.','route')}</div></div>`;}
function allocationsPage(){const plans=db.plans;return `${topSection('TRAVEL COORDINATION','Transport plans','Every allocated journey, organized in one place.',button('Plan new route','view-planner',{icon:'plus'}))}<div class="allocated-summary"><div>${icon('bus',21)} <strong>${plans.length}</strong> transport plans</div><div>${icon('users',21)} <strong>${plans.reduce((sum,p)=>sum+totalPeople(p.requestIds.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean)),0)}</strong> allocated travelers</div><div>${icon('checkCircle',21)} <strong>${plans.filter(p=>p.status==='completed').length}</strong> completed plans</div></div><div class="plans-grid">${plans.length?plans.map(plan=>{const reqs=plan.requestIds.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean);const total=totalPeople(reqs);return `<div class="plan-card"><div class="plan-card-head"><span class="plan-mode-icon">${transportArt(plan.mode)}</span><div><small>${esc(plan.id)}</small><h3>${esc(modeName(plan.mode))}</h3></div>${badge(plan.status)}</div><div class="plan-route-row">${icon('mapPin',17)} <strong>${esc(plan.pickup)}</strong> ${icon('arrowRight',16)} <strong>${esc(plan.drop)}</strong></div><div class="plan-divider"></div><div class="plan-details-row"><span>${icon('calendar',16)} ${formatDateTime(plan.departure)}</span><span>${icon('users',16)} ${total} / ${plan.capacity} travelers</span></div><div class="capacity-bar"><span style="width:${Math.min(100,Math.round(total/plan.capacity*100))}%"></span></div><div class="plan-card-foot"><span>${esc(plan.provider)}</span><button data-action="open-plan" data-id="${esc(plan.id)}">View plan ${icon('arrowRight',16)}</button></div></div>`;}).join(''):emptyState('No transport plans','Approved requests can be allocated from the route planning workspace.','bus')}</div>`;}
function peoplePage(){return `${topSection('TEAM DIRECTORY','People & roles','View the synthetic demo roster and add local preview profiles.',button('Add demo person','add-person',{icon:'plus'}))}<div class="people-info">${illustration('team')} ${icon('shield',18)} These records are demonstration profiles. Real user provisioning, Microsoft SSO and password management are not enabled.</div><div class="people-grid">${db.users.map(u=>`<div class="person-card">${avatar(u,'large')}<h3>${esc(u.name)}</h3><p>${esc(roleName(u.role))}</p><div class="person-meta"><span>${icon('building',15)} ${esc(u.department||'Operations')}</span><span>${icon('mapPin',15)} ${esc(u.location||'Location not set')}</span></div><span class="account-label">${u.login?.includes('Microsoft')?icon('shield',15):icon('user',15)} ${u.login?.includes('Microsoft')?'Microsoft user (demo)':'Local account (demo)'}</span></div>`).join('')}</div>`;}
function reportCounts(){const purposes=PURPOSES.map(name=>({name,count:db.requests.filter(r=>r.purpose===name).length}));const max=Math.max(1,...purposes.map(p=>p.count));return {purposes,max};}
function reportsPage(){const {purposes,max}=reportCounts();const all=db.requests,travelers=all.reduce((s,r)=>s+Number(r.people),0), groupable=getSuggestions(all).reduce((s,g)=>s+g.people,0);return `${topSection('OPERATIONS INSIGHTS','Travel insights','A quick snapshot of travel demand and planning progress.',button('Export requests CSV','export-csv',{variant:'btn-outline',icon:'download'}))}<div class="admin-stats">${metricCard('Total requests',all.length,'clipboard','blue','All time demo data')}${metricCard('Travelers requested',travelers,'users','purple','Across all journeys')}${metricCard('Potential group travelers',groupable,'route','mint','Heuristic only')}${metricCard('Urgent requests',all.filter(r=>r.priority==='emergency').length,'alert','orange','Require attention')}</div><div class="report-summary-banner">${illustration('analytics')}<div><p class="tiny-kicker">THE BIG PICTURE</p><h2>Every journey tells a story.</h2><p>Demand, allocation and activity from this browser's demo data.</p></div></div><div class="reports-grid">${sectionCard('Demand by travel purpose',`<div class="bar-chart">${purposes.map(p=>`<div class="bar-column"><span class="bar-value">${p.count}</span><div class="bar-track"><div class="bar-fill" style="height:${(p.count/max)*100}%"></div></div><small>${esc(p.name.replace(' visit',''))}</small></div>`).join('')}</div>`,'','chart')}${sectionCard('Status breakdown',`<div class="status-chart">${['draft','submitted','under_review','needs_info','approved','allocated','completed','rejected','cancelled'].map(s=>`<div class="status-chart-row"><span>${badge(s)}</span><div class="status-track"><i style="width:${(all.filter(r=>r.status===s).length/Math.max(all.length,1))*100}%"></i></div><strong>${all.filter(r=>r.status===s).length}</strong></div>`).join('')}</div>`,'','pie')}</div>${sectionCard('Recent audit activity',`<div class="activity-list audit-list">${db.activity.slice(0,15).map(eventRow).join('')}</div>`,button('Export requests CSV','export-csv',{variant:'btn-text',icon:'download'}),'clock')}<div class="info-line">${icon('info',17)} These figures reflect local demo data only, not real operational analytics or cost savings.</div>`;}
function settingsPage(){return `${topSection('APP PREFERENCES','Demo settings','View connection status, reset sample data and prepare for future integrations.')}<div class="settings-grid"><div class="surface-card settings-card"><div class="settings-art">${illustration('location-pin')}</div><h2>${icon('layers',21)} Workspace configuration</h2>${[['Storage','This browser only','mint'],['GitHub','Not connected','orange'],['Convex backend','Not connected','orange'],['Microsoft 365 SSO','Demo only','orange'],['Live mapping / ticketing','Not connected','orange']].map(([a,b,tone])=>`<div class="setting-row"><span>${a}</span><strong class="setting-value ${tone}">${b}</strong></div>`).join('')}<p class="micro-disclaimer">Company-owned services will be configured only after approval. No personal accounts are connected.</p></div><div class="surface-card settings-card"><h2>${icon('refresh',21)} Demo data controls</h2><p class="settings-copy">Try submitting requests and allocating transport. Your changes stay in this browser until you reset them or clear browser storage.</p><div class="storage-note">${icon('info',19)} Reset restores the original sample requests, people, plans and notification history.</div>${button('Reset all demo data','confirm-reset',{variant:'btn-danger-outline',icon:'refresh'})}</div><div class="surface-card settings-card"><h2>${icon('shield',21)} Production-readiness checklist</h2>${['Company GitHub repository and review policy','Company Convex team and environments','Microsoft Entra and local-user authentication','Server-enforced permissions and audit history','Approved routing and travel booking integrations'].map(t=>`<div class="checkline">${icon('checkCircle',17)} ${esc(t)}</div>`).join('')}<p class="micro-disclaimer">Items listed here are future implementation prerequisites, not completed integrations.</p></div></div>`;}
function helpPage(){return `${topSection('HELP CENTER','Travel made simple','Everything you need to know about submitting and managing requests.')}<div class="help-layout"><div class="surface-card help-main"><h2>How it works</h2>${[['01','Tell us where you are going','Choose a purpose, origin, destination and preferred departure time.','mapPin'],['02','Admin reviews your journey','The team may group compatible requests, arrange transport and coordinate details.','users'],['03','See your allocation','Check My trips once your travel is arranged. Look for a vehicle or ticket reference.','bus'],['04','Keep your details handy','Your request page tracks progress and notifies you of changes.','bell']].map(([n,t,s,ic])=>`<div class="help-row"><span class="help-number">${n}</span><span class="soft-icon blue">${icon(ic,20)}</span><span><strong>${t}</strong><p>${s}</p></span></div>`).join('')}</div><div class="help-side"><div class="guide-art">${illustration('planning')}</div><div class="tip-card"><span class="tip-star">${icon('sparkle',20)}</span><strong>Need urgent travel?</strong><p>Choose Emergency when submitting your request and tell Admin why it’s urgent. Emergency does not guarantee automatic booking.</p>${button('Create urgent request','urgent-request',{variant:'btn-soft',icon:'plus'})}</div><div class="surface-card contact-card"><h3>Need assistance?</h3><p>Contact your company's Travel Admin or site coordinator through your normal company channels.</p><span>${icon('info',17)} Contact details are not connected in this demo.</span></div></div></div>`;}
const modeIcon=m=>({bus:'bus',van:'bus',car:'car',train:'train',flight:'plane',sea:'ship'}[m]||'bus');
function modalShell(){const m=ui.modal;let title='',content='',width='';if(m.type==='request'){const r=db.requests.find(r=>r.id===m.id);title=`Travel request · ${r?.id||''}`;content=r?requestModal(r):'<p>Request not found.</p>';width='modal-wide';}
 if(m.type==='status'){const r=db.requests.find(r=>r.id===m.id);title=m.target==='rejected'?'Reject request':m.target==='needs_info'?'Request clarification':m.target==='cancelled'?'Cancel request':`Update request status`;content=`<p class="modal-intro">${esc(r?.id||'')} · ${esc(r?.destination||'')}</p><form id="status-form"><label class="form-field"><span class="field-label">${m.target==='rejected'?'Reason for rejection':m.target==='needs_info'?'Clarification needed':'Reason'} <i>*</i></span><textarea name="reason" rows="4" placeholder="Provide a clear reason for the traveler..." required></textarea></label><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn ${m.target==='rejected'?'btn-danger':'btn-primary'}">Confirm action ${icon('arrowRight',17)}</button></div></form>`;}
 if(m.type==='group-confirm'){title='Confirm group review';const rs=m.ids.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean);content=`<div class="modal-intro">You're about to review and approve ${rs.length} request${rs.length===1?'':'s'} for a shared transport plan. ${totalPeople(rs)} traveler${totalPeople(rs)===1?'':'s'} will be included.</div><div class="approval-list">${rs.map(r=>`<div>${avatar(userById(r.userId),'small')}<span><strong>${esc(userById(r.userId).name)}</strong><small>${esc(r.origin)} · ${statusLabel(r.status)}</small></span></div>`).join('')}</div><div class="warning-box">${icon('alert',19)} Verify actual route feasibility, required approvals and departure compatibility. The app has not checked live road routing or supplier availability.</div><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">Back</button><button class="btn btn-primary" data-action="confirm-group-approval">Approve & configure plan ${icon('arrowRight',17)}</button></div>`;}
 if(m.type==='allocate'){title='Allocate transportation';width='modal-wide';content=allocationModal(m.ids);}
 if(m.type==='plan'){const p=db.plans.find(v=>v.id===m.id);title=`Transport plan · ${p?.id||''}`;content=p?planModal(p):'<p>Plan not found.</p>';width='modal-wide';}
 if(m.type==='edit-plan'){const p=db.plans.find(v=>v.id===m.id);title='Edit transport allocation';content=p?allocationModal(p.requestIds,p):'<p>Plan not found.</p>';width='modal-wide';}
 if(m.type==='pass'){const p=db.plans.find(v=>v.id===m.id);title='Preview travel itinerary';content=p?passModal(p):'<p>Itinerary not found.</p>';width='modal-wide';}
 if(m.type==='person'){title='Add a demo person';content=`<p class="modal-intro">Create a synthetic local preview profile. Real credentials are not generated.</p><form id="person-form"><div class="form-grid"><label class="form-field field-span"><span class="field-label">Full name</span><input name="name" placeholder="e.g. Kavya Rao" required/></label><label class="form-field"><span class="field-label">Role</span><select name="role"><option value="worker">Site worker</option><option value="employee">Employee</option><option value="manager">Manager</option><option value="senior_manager">Senior manager</option></select></label><label class="form-field"><span class="field-label">Department</span><input name="department" value="Operations"/></label><label class="form-field field-span"><span class="field-label">Location</span><input name="location" placeholder="e.g. Hyderabad"/></label></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Add demo person ${icon('plus',17)}</button></div></form>`;}
 if(m.type==='cancel'){const r=db.requests.find(r=>r.id===m.id);title='Cancel travel request';content=`<p class="modal-intro">Cancel ${esc(r?.id)} to ${esc(r?.destination)}? Admin will be notified.</p><form id="cancel-form"><label class="form-field"><span class="field-label">Reason for cancellation</span><textarea name="reason" rows="3" placeholder="Optional reason"></textarea></label><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Keep request</button><button type="submit" class="btn btn-danger">Cancel request</button></div></form>`;}
 if(m.type==='reset'){title='Reset demo data?';content=`<p class="modal-intro">This will erase your local changes and restore all original sample travel requests, allocations and notifications.</p><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">Keep my changes</button><button class="btn btn-danger" data-action="reset-demo">Reset demo data ${icon('refresh',17)}</button></div>`;}
 return `<div class="modal-overlay" data-action="overlay-close"><section class="dialog dialog-${m.type} ${width}" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="modal-head"><div><p class="tiny-kicker">PRORACK MOVE</p><h2>${esc(title)}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x',21)}</button></div><div class="modal-scroll">${content}</div></section></div>`;}
function requestModal(r){const owner=userById(r.userId);const p=db.plans.find(p=>p.id===r.planId);const isOwner=r.userId===sessionId;return `<div class="request-modal-intro"><div class="modal-route-head"><span class="soft-icon blue">${icon('route',23)}</span><div><strong>${esc(r.origin)} ${icon('arrowRight',18)} ${esc(r.destination)}</strong><span>${shortDate(r.departDate)} · ${esc(formatTime(r.departTime))} · ${r.people} traveler${r.people!==1?'s':''}</span></div></div><div>${badge(r.status)} ${priorityBadge(r.priority)}</div></div><div class="modal-columns"><div><h3 class="modal-subheading">Request details</h3><div class="modal-detail-grid">${profileLine('Traveler',owner.name)}${profileLine('Department',r.department)}${profileLine('Purpose',r.purpose)}${profileLine('Priority',r.priority==='emergency'?'Emergency':'Planned')}${profileLine('Departure',`${niceDate(r.departDate)} · ${formatTime(r.departTime)}`)}${profileLine('Required arrival',arrivalSummary(r))}${profileLine('Return',formatSchedule(r.returnDate,r.returnTime))}${profileLine('Preferred mode',canRequestMode(owner.role)?modeName(r.preferredMode)||'None': 'Managed by Admin')}${profileLine('Site / project',r.site)}</div>${r.notes?`<div class="notes-box"><strong>Travel notes</strong><p>${esc(r.notes)}</p></div>`:''}${r.roster?`<div class="notes-box"><strong>Group roster notes</strong><p>${esc(r.roster)}</p></div>`:''}${p?`<div class="allocation-details"><h3>Assigned transport</h3>${profileLine('Mode',modeName(p.mode))}${profileLine('Pickup',p.pickup)}${profileLine('Departure',formatDateTime(p.departure))}${profileLine('Provider',p.provider)}${profileLine('Reference',p.bookingRef||'Not recorded')}${p.notes?profileLine('Pickup instructions',p.notes):''}</div>`:''}</div><div><h3 class="modal-subheading">Journey progress</h3>${timeline(r,db.activity)}<h3 class="modal-subheading" style="margin-top:24px">Recent updates</h3><div class="mini-activity">${db.activity.filter(a=>a.requestId===r.id).slice(0,4).map(a=>`<p>${esc(a.message)}<small>${timeAgo(a.time)}</small></p>`).join('')||'<p>No changes recorded yet.</p>'}</div></div></div><div class="modal-actions wrap">${p?`<button class="btn btn-outline" data-action="view-pass" data-id="${esc(p.id)}">${icon('clipboard',16)} View travel pass</button>`:''}${isAdmin()?`<div class="modal-action-cluster">${['submitted','under_review','needs_info'].includes(r.status)?`${r.status!=='needs_info'?`<button class="btn btn-success" data-action="approve-request" data-id="${esc(r.id)}">${icon('check',17)} Approve</button><button class="btn btn-outline" data-action="status-action" data-id="${esc(r.id)}" data-target="needs_info">Need more info</button>`:'<span class="pending-answer">Awaiting traveler clarification</span>'}<button class="btn btn-danger-outline" data-action="status-action" data-id="${esc(r.id)}" data-target="rejected">Reject</button>`:''}${r.status==='approved'?`<button class="btn btn-primary" data-action="single-plan" data-id="${esc(r.id)}">Allocate transport ${icon('arrowRight',17)}</button>`:''}${r.status==='allocated'?`<button class="btn btn-success" data-action="complete-request-plan" data-id="${esc(r.planId||'')}">Mark trip completed</button>`:''}</div>`:isOwner?`<div class="modal-action-cluster">${['draft','needs_info'].includes(r.status)?button(r.status==='draft'?'Resume draft':'Update & resubmit','resume-draft',{variant:'btn-primary',data:`data-id="${esc(r.id)}"`}) :''}${['submitted','under_review','needs_info','draft'].includes(r.status)?button('Cancel request','cancel-request',{variant:'btn-danger-outline',data:`data-id="${esc(r.id)}"`}) :''}</div>`:''}<button class="btn btn-outline" data-action="close-modal">Close</button></div>`;}
function allocationModal(ids,existingPlan=null){
 const rs=ids.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean),people=totalPeople(rs);
 const suggested=existingPlan?.mode||(people>=25?(key(rs[0]?.destination||'').includes('bhiwandi')?'train':'bus'):people>=5?'van':people>=2?'car':'car');
 const mode=MODES.find(x=>x.id===suggested)||MODES[0], pref=(name,fallback='')=>esc(existingPlan?.[name]??fallback);
 return `<div class="modal-intro">${existingPlan?'Update an existing':'Prepare a manual'} transport allocation for <strong>${people} travelers</strong> across ${rs.length} request${rs.length!==1?'s':''}. This does not create a live booking.</div><div class="allocation-requests">${rs.map(r=>`<span>${avatar(userById(r.userId),'tiny')} ${esc(userById(r.userId).name)} <b>× ${r.people}</b></span>`).join('')}</div><form id="${existingPlan?'edit-allocation-form':'allocation-form'}"><input type="hidden" name="requestIds" value="${esc(ids.join(','))}"/><h3 class="modal-subheading">Choose transport mode</h3><div class="allocation-modes">${MODES.map(m=>`<label class="allocation-mode"><input type="radio" name="mode" value="${m.id}" ${m.id===suggested?'checked':''}><span>${transportArt(m.id)}<strong>${esc(m.label)}</strong><small>Typical ${m.seats} seats*</small></span></label>`).join('')}</div><div class="modal-form-grid"><label class="form-field"><span class="field-label">Capacity <i>*</i></span><input type="number" min="1" step="1" max="5000" name="capacity" value="${pref('capacity',mode.seats)}" required/><small class="field-hint">Manually verify actual seating.</small></label>${dateTimeField('Departure','departure',existingPlan?.departure||`${rs[0]?.departDate||dateOffset(2)}T${rs[0]?.departTime||'08:00'}`,{required:true})}<label class="form-field"><span class="field-label">Pickup / boarding point <i>*</i></span><input name="pickup" placeholder="e.g. Kothur main gate" value="${pref('pickup',rs[0]?.origin||'')}" required/></label><label class="form-field"><span class="field-label">Destination</span><input name="drop" value="${pref('drop',rs[0]?.destination||'')}" /></label><label class="form-field"><span class="field-label">Provider / operator</span><input name="provider" placeholder="e.g. Company transport" value="${pref('provider')}"/></label><label class="form-field"><span class="field-label">Vehicle / service details</span><input name="identifier" placeholder="Registration or carrier info" value="${pref('identifier')}"/></label><label class="form-field"><span class="field-label">Booking reference (if confirmed)</span><input name="bookingRef" placeholder="Leave blank if not booked" value="${pref('bookingRef')}"/></label><label class="form-field"><span class="field-label">Admin notes</span><input name="notes" placeholder="Pickup and coordination notes" value="${pref('notes')}"/></label></div><div class="warning-box">${icon('info',19)} *Typical seat counts are editable placeholders, not confirmed inventory. Validate the actual route, capacity, travelers and any required approvals before saving.</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${existingPlan?'Save updated itinerary':'Confirm allocation'} ${icon('check',17)}</button></div></form>`;
}

function planModal(p){const reqs=p.requestIds.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean);return `<div class="plan-modal-summary"><span class="plan-mode-icon">${transportArt(p.mode)}</span><div><strong>${esc(modeName(p.mode))}</strong><small>${formatDateTime(p.departure)} · ${totalPeople(reqs)} travelers</small></div>${badge(p.status)}</div><div class="modal-detail-grid">${profileLine('Pickup / boarding',p.pickup)}${profileLine('Destination',p.drop)}${profileLine('Provider',p.provider)}${profileLine('Vehicle / service',p.identifier||'To be confirmed')}${profileLine('Seats',`${totalPeople(reqs)} / ${p.capacity}`)}${profileLine('Booking reference',p.bookingRef||'Not recorded')}</div>${p.notes?`<div class="notes-box"><strong>Admin notes</strong><p>${esc(p.notes)}</p></div>`:''}<h3 class="modal-subheading" style="margin-top:20px">Included requests</h3><div class="approval-list">${reqs.map(r=>`<div>${avatar(userById(r.userId),'small')}<span><strong>${esc(userById(r.userId).name)}</strong><small>${esc(r.id)} · ${r.people} traveler${r.people!==1?'s':''}</small></span>${badge(r.status)}</div>`).join('')}</div><div class="modal-actions">${p.status==='allocated'?`<button class="btn btn-outline" data-action="edit-plan" data-id="${esc(p.id)}">${icon('settings',16)} Edit details</button>`:''}<button class="btn btn-outline" data-action="view-pass" data-id="${esc(p.id)}">${icon('clipboard',16)} Preview itinerary</button>${p.status==='allocated'?`<button class="btn btn-success" data-action="complete-plan" data-id="${esc(p.id)}">${icon('check',17)} Mark completed</button>`:''}<button class="btn btn-outline" data-action="close-modal">Close</button></div>`;}
function passModal(plan){
 const all=plan.requestIds.map(id=>db.requests.find(r=>r.id===id)).filter(Boolean);
 const included=isAdmin()?all:all.filter(r=>r.userId===sessionId);
 if(!included.length)return '<p class="modal-intro">This demo itinerary is only visible to its assigned traveler or Travel Admin.</p>';
 const travelers=totalPeople(included);
 return `<div class="pass-intro">This is a printable <strong>planning summary</strong>. It is NOT a confirmed boarding pass or valid ticket.</div><article class="printable-pass"><div class="pass-watermark">DEMO · NOT A TICKET</div><header class="pass-header"><div><span class="pass-brand">PRORACK <strong>MOVE</strong></span><small>EMPLOYEE TRANSPORT · PLANNING SUMMARY</small></div><span class="pass-status">LOCAL DEMO</span></header><div class="pass-hero"><span>${icon(modeIcon(plan.mode),25)} ${esc(modeName(plan.mode))}</span><h2>${esc(plan.drop)}</h2><p>${esc(plan.pickup)} ${icon('arrowRight',16)} ${esc(plan.drop)}</p></div><div class="pass-grid"><div><small>TRAVEL DATE & TIME</small><strong>${esc(formatDateTime(plan.departure))}</strong></div><div><small>TRAVELERS ON THIS COPY</small><strong>${travelers}</strong></div><div><small>PLAN REFERENCE</small><strong>${esc(plan.id)}</strong></div><div><small>STATUS</small><strong>${esc(statusLabel(plan.status))}</strong></div><div><small>PROVIDER / OPERATOR</small><strong>${esc(plan.provider||'To be confirmed')}</strong></div><div><small>VEHICLE / SERVICE</small><strong>${esc(plan.identifier||'To be confirmed')}</strong></div><div><small>BOOKING REF (AS ENTERED)</small><strong>${esc(plan.bookingRef||'Not recorded')}</strong></div><div><small>PICKUP / BOARDING</small><strong>${esc(plan.pickup)}</strong></div></div><div class="pass-passengers"><h3>${isAdmin()?'Included request owners':'Traveler request'}</h3>${included.map(r=>`<div><strong>${esc(userById(r.userId).name)}</strong><span>${esc(r.id)} · ${r.people} traveler${Number(r.people)===1?'':'s'}</span></div>`).join('')}</div>${plan.notes?`<div class="pass-notes"><strong>Coordination notes</strong><p>${esc(plan.notes)}</p></div>`:''}<footer class="pass-disclaimer">DEMO ONLY · This document does not authorize travel or confirm reservations. Contact ProRack Travel Admin for final instructions.</footer></article><div class="modal-actions pass-actions"><button class="btn btn-outline" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="print-pass">${icon('download',17)} Print / Save as PDF</button></div>`;
}
function captureWizard(validate=false){const form=document.getElementById('wizard-form');if(!form)return;for(const [name,value] of Object.entries(formData(form,validate))){if(typeof value==='string')ui.wizard[name]=value;}if(!isAdmin())ui.wizard.userId=sessionId;}
function checkStep(){const w=ui.wizard,s=ui.wizardStep;if(s===0){if(!w.purpose)throw Error('Choose a travel purpose.');}
 if(s===1){const timingErrors=validateJourneyTiming(w);if(timingErrors.length)throw Error(timingErrors[0]);if(!w.origin?.trim()||!w.destination?.trim())throw Error('Please enter your origin and destination.');if(key(w.origin)===key(w.destination))throw Error('Origin and destination must be different.');if(!w.departDate||!w.departTime)throw Error('Choose a departure date and time.');if(w.departDate<dateOffset(0))throw Error('Departure date cannot be in the past.');if(w.returnDate&&w.returnDate<w.departDate)throw Error('Return date cannot be before departure.');}
 if(s===2){if(!Number.isInteger(Number(w.people))||Number(w.people)<1||Number(w.people)>500)throw Error('Enter a number of travelers between 1 and 500.');if(w.priority==='emergency'&&w.notes.trim().length<8)throw Error('Emergency travel requires a clear reason (at least 8 characters).');}
}
function openGroup(groupId){ui.view='planner';ui.selectedGroup=groupId;ui.selectedIds=null;ui.modal=null;render();}
function openAllocation(ids){ui.modal={type:'allocate',ids};render();}
function formData(form,validate=true){syncTimeControls(form,validate);const values=Object.fromEntries(new FormData(form).entries());for(const group of form.querySelectorAll?.('[data-datetime-field]')||[])delete values[group.dataset.datetimeField+'Time'];return values;}
function processWizard(asDraft=false){captureWizard(!asDraft);const requester=userById(ui.wizard.userId);const w={...ui.wizard};if(!canRequestMode(requester.role))w.preferredMode='';
 if(!asDraft){const errors=validateRequest(w,requester.role);if(errors.length){notify(errors[0],'error');return;} }
 const created=mutate(()=>{
  if(ui.editingDraft){const old=db.requests.find(r=>r.id===ui.editingDraft);if(!old||!['draft','needs_info'].includes(old.status)||(!isAdmin()&&old.userId!==sessionId))throw Error('This request cannot be edited.');Object.assign(old,w,{status:asDraft?'draft':'submitted',preferredMode:w.preferredMode});appendEvent(db,currentUser().id,asDraft?'draft':'submitted',`${old.id}: ${asDraft?'Draft updated':'Updated request submitted for review'}.`,old.id,asDraft?null:'usr-admin');return old;}
  return asDraft?addDraft(db,w,currentUser()):addRequest(db,w,currentUser());
 },asDraft?'Draft saved to this browser.':'Travel request submitted successfully!');
 if(created){ui.editingDraft=null;ui.wizard=defaultWizard();ui.wizardStep=0;ui.view=isAdmin()?'admin-requests':'requests';render();}
}
function roleSelect(id){if(!db.users.some(u=>u.id===id))return;sessionId=id;saveSession(id);ui.view=isAdmin()?'dashboard':'home';ui.roleMenuOpen=false;ui.notificationOpen=false;ui.navOpen=false;ui.modal=null;ui.wizard=defaultWizard();ui.wizardStep=0;ui.editingDraft=null;window.scrollTo(0,0);render();}
function safeHandle(action,el){
 const id=el.dataset.id,me=currentUser();
 switch(action){
  case 'tour-start':tourJump(0);return;
  case 'tour-close':ui.tourOpen=false;render();return;
  case 'tour-next':tourJump(ui.tourIndex+1);return;
  case 'tour-prev':tourJump(ui.tourIndex-1);return;
  case 'tour-step':tourJump(Number(id));return;
  case 'print-pass':window.print();return;
  case 'view-pass':{const p=db.plans.find(x=>x.id===id);if(!p||(!isAdmin()&&!p.requestIds.some(rid=>db.requests.some(r=>r.id===rid&&r.userId===sessionId)))){notify('This itinerary is not available to your demo profile.','error');return;}ui.modal={type:'pass',id};render();return;}
  case 'edit-plan':ui.modal={type:'edit-plan',id};render();return;
  case 'select-persona':ui.selectedPersona=id;render();return;
  case 'enter-demo':roleSelect(ui.selectedPersona);return;
  case 'logout':sessionId=null;saveSession(null);ui.view='home';ui.modal=null;ui.roleMenuOpen=false;render();return;
  case 'switch-persona':roleSelect(id);return;
  case 'workspace-menu':ui.navOpen=!ui.navOpen;render();return;
  case 'role-menu':ui.roleMenuOpen=!ui.roleMenuOpen;ui.notificationOpen=false;render();return;
  case 'notifications':ui.notificationOpen=!ui.notificationOpen;ui.roleMenuOpen=false;render();return;
  case 'mark-read':db.notifications.filter(n=>n.userId===sessionId).forEach(n=>n.read=true);remember();ui.notificationOpen=true;return;
  case 'open-notification':{const n=db.notifications.find(v=>v.id===id);if(n){n.read=true;saveDB(db);ui.notificationOpen=false;if(n.requestId){ui.modal={type:'request',id:n.requestId};}render();}return;}
  case 'new-request':case 'view-trips':case 'view-requests':case 'view-admin-requests':case 'view-reports':case 'view-planner':{
   const to={'new-request':'new','view-trips':'trips','view-requests':'requests','view-admin-requests':'admin-requests','view-reports':'reports','view-planner':'planner'}[action];ui.editingDraft=null;go(to);return;
  }
  case 'urgent-request':ui.editingDraft=null;go('new');ui.wizard.priority='emergency';render();return;
  case 'choose-purpose':ui.wizard.purpose=id;render();return;
  case 'priority':ui.wizard.priority=id;render();return;
  case 'choose-mode':ui.wizard.preferredMode=id;render();return;
  case 'next-step':try{captureWizard(true);checkStep();ui.wizardStep=Math.min(3,ui.wizardStep+1);render();window.scrollTo({top:0,behavior:'smooth'});}catch(e){notify(e.message,'error');}return;
  case 'prev-step':captureWizard();ui.wizardStep=Math.max(0,ui.wizardStep-1);render();return;
  case 'save-draft':processWizard(true);return;
  case 'submit-request':processWizard(false);return;
  case 'request-tab':ui.requestTab=id;render();return;
  case 'admin-filter':ui.adminFilter=id;render();return;
  case 'open-request':ui.modal={type:'request',id};render();return;
  case 'close-modal':ui.modal=null;render();return;
  case 'overlay-close':if(el===eventTargetRoot){ui.modal=null;render();}return;
  case 'dismiss-toast':ui.notice=null;render();return;
  case 'approve-request':{const approved=mutate(()=>updateStatus(db,id,'approved',me),'Travel request approved.');if(approved){ui.modal=null;render();}return;}
  case 'status-action':ui.modal={type:'status',id,target:el.dataset.target};render();return;
  case 'cancel-request':ui.modal={type:'cancel',id};render();return;
  case 'resume-draft':{const r=db.requests.find(x=>x.id===id);if(!r||r.userId!==sessionId||!['draft','needs_info'].includes(r.status)){notify('You cannot edit this request.','error');return;}ui.editingDraft=id;ui.wizard={...defaultWizard(),...r};ui.wizardStep=0;ui.modal=null;go('new');ui.editingDraft=id;ui.wizard={...r};ui.wizardStep=0;render();return;}
  case 'choose-group':openGroup(id);return;
  case 'toggle-member':return; // changed through the delegated change handler
  case 'start-group-plan':{const suggestion=getSuggestions(db.requests).find(s=>s.id===ui.selectedGroup)||getSuggestions(db.requests)[0];const ids=(ui.selectedIds??suggestion?.requestIds??[]).filter(Boolean);if(!ids.length){notify('Select at least one traveler request.','error');return;}const rs=ids.map(x=>db.requests.find(r=>r.id===x));if(rs.some(r=>!r||!['submitted','under_review','approved'].includes(r.status))){notify('Resolve clarification requests before planning this group.','error');return;}ui.modal={type:'group-confirm',ids};render();return;}
  case 'confirm-group-approval':{const ids=ui.modal?.ids||[];const approved=mutate(()=>{for(const r of ids.map(x=>db.requests.find(req=>req.id===x))){if(r&&['submitted','under_review'].includes(r.status))updateStatus(db,r.id,'approved',me);}return ids;},'Requests reviewed and approved.');if(approved)openAllocation(ids);return;}
  case 'single-plan':openAllocation([id]);return;
  case 'open-plan':ui.modal={type:'plan',id};render();return;
  case 'complete-plan':case 'complete-request-plan':{const result=mutate(()=>completePlan(db,id,me),'Trip marked as completed.');if(result!==null){ui.modal=null;render();}return;}
  case 'add-person':ui.modal={type:'person'};render();return;
  case 'confirm-reset':ui.modal={type:'reset'};render();return;
  case 'reset-demo':db=resetDB();ui.modal=null;ui.selectedGroup=null;ui.selectedIds=null;ui.adminFilter='all';ui.requestTab='all';ui.requestQuery='';ui.query='';notify('Sample data restored. You are ready to demo again.');return;
  case 'export-csv':exportCSV();return;
  default:return;
 }
}
let eventTargetRoot=null;
document.addEventListener('click',event=>{
 const nav=event.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
 const button=event.target.closest('[data-action]');if(!button)return;
 if(button.dataset.action==='overlay-close'&&event.target!==button)return;
 eventTargetRoot=event.target;
 try{safeHandle(button.dataset.action,button);}catch(e){notify(e instanceof Error?e.message:'Unable to complete that action.','error');}
});
document.addEventListener('change',event=>{
 const target=event.target;
 if(target.closest?.('[data-time-field],[data-datetime-field]')){syncTimeControls(target.form);if(ui.view==='new')captureWizard();return;}
 if(target instanceof HTMLInputElement && target.dataset.action==='toggle-member'){
   const suggestion=getSuggestions(db.requests).find(s=>s.id===ui.selectedGroup)||getSuggestions(db.requests)[0];
   const ids=ui.selectedIds?[...ui.selectedIds]:[...(suggestion?.requestIds??[])];
   ui.selectedIds=target.checked?[...new Set([...ids,target.dataset.id])]:ids.filter(v=>v!==target.dataset.id);
   render();return;
 }
 if(target instanceof HTMLSelectElement && target.name==='userId'&&ui.view==='new'){captureWizard();ui.wizard.userId=target.value;render();return;}
 if(target instanceof HTMLInputElement && target.name==='mode'&&target.closest('#allocation-form, #edit-allocation-form')){
   const seats=MODES.find(m=>m.id===target.value)?.seats;
   const cap=document.querySelector('#allocation-form [name="capacity"], #edit-allocation-form [name="capacity"]');if(cap&&seats)cap.value=String(seats);
 }
});
document.addEventListener('input',event=>{
 const target=event.target;
 if(target instanceof HTMLElement && target.closest('#wizard-form') && 'name' in target && target.name){ui.wizard[target.name]=target.value;}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();let values;try{values=formData(form);}catch(e){notify(e.message,'error');return;}const me=currentUser();
 if(form.id==='employee-search-form'){ui.requestQuery=String(values.query||'');render();return;}
 if(form.id==='search-form'){ui.query=String(values.query||'');render();return;}
 if(form.id==='status-form'){const id=ui.modal.id,to=ui.modal.target;const success=mutate(()=>updateStatus(db,id,to,me,String(values.reason||'')),'Decision saved and traveler notified.');if(success){ui.modal=null;render();}return;}
 if(form.id==='cancel-form'){const id=ui.modal.id;const success=mutate(()=>cancelOwnRequest(db,id,me,String(values.reason||'')),'Request cancelled and Admin notified.');if(success){ui.modal=null;render();}return;}
 if(form.id==='person-form'){const user=mutate(()=>addPerson(db,values,me),'Demo user created.');if(user){ui.modal=null;render();}return;}
 if(form.id==='edit-allocation-form'){
   const plan=mutate(()=>updatePlan(db,ui.modal.id,values,me),'Itinerary updated. Assigned travelers notified.');
   if(plan){ui.modal={type:'plan',id:plan.id};render();}return;
 }
 if(form.id==='allocation-form'){
   const requestIds=String(values.requestIds||'').split(',').filter(Boolean);
   const plan=mutate(()=>createPlan(db,{...values,requestIds},me),'Transport successfully allocated. All travelers notified.');
   if(plan){ui.modal=null;ui.view='allocations';ui.selectedIds=null;render();}return;
 }
});
document.addEventListener('keydown',event=>{
 if(event.key==='Tab'&&ui.modal&&document.querySelectorAll){const dialog=document.querySelector('.dialog');const targets=[...(dialog?.querySelectorAll('button:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[])].filter(el=>el.getClientRects().length);const first=targets[0],last=targets.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialog)){event.preventDefault();first?.focus();}}
 if(event.key==='Escape'&&(ui.modal||ui.roleMenuOpen||ui.notificationOpen||ui.navOpen)){ui.modal=null;ui.roleMenuOpen=false;ui.notificationOpen=false;ui.navOpen=false;render();}
});
function exportCSV(){const keys=['id','userId','purpose','priority','origin','destination','departDate','departTime','requiredArrivalDate','requiredArrival','returnDate','returnTime','people','status','preferredMode','planId'];const rows=[keys.join(','),...db.requests.map(r=>keys.map(k=>`"${String(k==='userId'?userById(r.userId).name:['departTime','requiredArrival','returnTime'].includes(k)&&r[k]?formatTime(r[k]):r[k]??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')}"`).join(','))];const blob=new Blob(['\uFEFF'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`prorack-move-requests-${dateOffset(0)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported from local demo data.');}
// First paint
render();
